def detect_locale(
    query_lang: Optional[str] = None,
    cookie_lang: Optional[str] = None,
    accept_language: Optional[str] = None,
) -> str:
    """Detect locale from query param > cookie > Accept-Language header.

    Returns a supported locale string.
    """
    # 1. Query param (?lang=zh-tw)
    if query_lang and query_lang.lower() in SUPPORTED_LOCALES:
        return query_lang.lower()

    # 2. Cookie
    if cookie_lang and cookie_lang.lower() in SUPPORTED_LOCALES:
        return cookie_lang.lower()

    # 3. Accept-Language header
    if accept_language:
        for part in accept_language.split(","):
            lang = part.split(";")[0].strip().lower()
            if lang in SUPPORTED_LOCALES:
                return lang
            # Map common variants
            if lang.startswith("zh"):
                return "zh-tw"
            if lang.startswith("ko"):
                return "ko"

    return DEFAULT_LOCALE

def t(key: str, locale: str = DEFAULT_LOCALE) -> str:
    """Translate a key to the given locale. Falls back to English.

    Returns a Markup object so Jinja2 won't double-escape embedded HTML
    (e.g. <strong>, <code>).  All translation content is developer-controlled.

    Returns empty string for missing keys so Jinja2 ``t(...) if t else 'fallback'``
    patterns use the English fallback text defined in the template.
    """
    entry = TRANSLATIONS.get(key)
    if entry is None:
        return Markup("")
    return Markup(entry.get(locale, entry.get("en", "")))

def make_translator(locale: str):
    """Create a locale-bound translation function for Jinja2 templates."""
    def _t(key: str) -> Markup:
        return t(key, locale)
    return _t
